<?php require __DIR__.'/bootstrap.php'; if($_SERVER['REQUEST_METHOD']!=='POST'){redirect('index.php');}csrf_check();$email=trim((string)($_POST['email']??''));if(!filter_var($email,FILTER_VALIDATE_EMAIL)){redirect('index.php?newsletter=invalid');}$items=read_json('subscribers.json',[]);foreach($items as $s)if(strtolower($s['email'])===strtolower($email)){redirect('index.php?newsletter=exists');}$items[]=['id'=>bin2hex(random_bytes(6)),'email'=>$email,'created_at'=>date(DATE_ATOM),'status'=>'subscribed','consent'=>true];write_json('subscribers.json',$items);add_notification('Newsletter subscription','A new subscriber joined: '.$email,'newsletter');redirect('index.php?newsletter=success');
